#  python ner_agent_auto.py "Who played Neo or Morpheus in The Matrix?" " --verbose
#  python ner_agent_auto.py "Who act  in matrix?"  --verbose
#  python ner_agent_auto.py "Who played neo or morphes in matrix?" --verbose
